'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );


// MAIN //

/**
* Returns the mode of a Burr (type III) distribution with first shape parameter `c` and second shape parameter `d`.
*
* @param {PositiveNumber} c - first shape parameter
* @param {PositiveNumber} d - second shape parameter
* @returns {NonNegativeNumber} mode
*
* @example
* var y = mode( 2.0, 1.0 );
* // returns ~0.577
*
* @example
* var y = mode( 4.0, 12.0 );
* // returns ~1.751
*
* @example
* var y = mode( 8.0, 2.0 );
* // returns ~1.066
*
* @example
* var y = mode( 1.0, 1.0 );
* // returns 0.0
*
* @example
* var y = mode( NaN, 2.0 );
* // returns NaN
*
* @example
* var y = mode( 2.0, NaN );
* // returns NaN
*
* @example
* var y = mode( -1.0, 2.0 );
* // returns NaN
*
* @example
* var y = mode( 2.0, -1.0 );
* // returns NaN
*/
function mode( c, d ) {
	if (
		isnan( c ) ||
		isnan( d ) ||
		c <= 0.0 ||
		d <= 0.0
	) {
		return NaN;
	}
	if ( c*d <= 1.0 ) {
		return 0.0;
	}
	return pow( ( ( c*d ) - 1.0 ) / ( c + 1.0 ), 1.0/c );
}


// EXPORTS //

module.exports = mode;
